//! Guards the checked-in SDK type definitions against `schema.json`.
//!
//! `sdk/typescript/rustren.d.ts` and `sdk/python/rustren_types.py` are generated by
//! `scripts/gen_sdk.py`. These tests fail when either file drifts, so `cargo test`
//! catches a stale SDK even on a machine without Python.
//!
//! Two checks run:
//! 1. every schema property appears in the matching generated type, and every
//!    generated enum literal exists in the schema (no invented names/values);
//! 2. when `python3` is available, `gen_sdk.py --check` must pass byte-for-byte.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};
use std::process::Command;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn schema() -> serde_json::Value {
    serde_json::from_str(include_str!("../schema.json")).expect("schema.json must be valid JSON")
}

fn read(path: &str) -> String {
    std::fs::read_to_string(root().join(path)).unwrap_or_else(|e| panic!("read {path}: {e}"))
}

/// Body of `export interface NAME ... {` up to the matching closing `}` at column 0.
fn ts_interface(text: &str, name: &str) -> String {
    let start = text
        .lines()
        .position(|l| l.starts_with(&format!("export interface {name} ")))
        .unwrap_or_else(|| panic!("rustren.d.ts has no interface {name}"));
    let mut out = String::new();
    for line in text.lines().skip(start + 1) {
        if line == "}" {
            break;
        }
        out.push_str(line);
        out.push('\n');
    }
    out
}

/// Body of a class or functional `TypedDict` block, whichever form was emitted.
fn py_class(text: &str, name: &str) -> String {
    let class_marker = format!("class {name}(");
    let functional_marker = format!("{name} = TypedDict(");
    let start = text
        .lines()
        .position(|l| l.starts_with(&class_marker) || l.starts_with(&functional_marker))
        .unwrap_or_else(|| panic!("rustren_types.py has no TypedDict {name}"));
    let functional = text.lines().nth(start).unwrap().starts_with(&functional_marker);

    let mut out = String::new();
    if functional {
        // `"key": type,` lines inside the dict literal.
        for line in text.lines().skip(start + 1) {
            let line = line.trim();
            if line.starts_with("},") || line.starts_with(')') {
                break;
            }
            if let Some((key, _)) = line
                .strip_prefix('"')
                .and_then(|rest| rest.split_once("\": "))
            {
                out.push_str(key);
                out.push('\n');
            }
        }
        assert!(!out.is_empty(), "{name} has no fields");
        return out;
    }

    for line in text.lines().skip(start + 1) {
        if line.trim().is_empty() {
            continue;
        }
        if !line.starts_with(' ') {
            break;
        }
        out.push_str(line);
        out.push('\n');
    }
    assert!(!out.is_empty(), "{name} has no fields");
    out
}

/// Field names from generated interface/class bodies, ignoring docstrings and strings.
fn field_names(body: &str, py: bool) -> BTreeSet<String> {
    body.lines()
        .filter_map(|line| {
            let line = line.trim();
            if line.is_empty() || line.starts_with("/*") || line.starts_with("//") {
                return None;
            }
            if py {
                if line.starts_with("\"\"\"") || line.starts_with("class ") {
                    return None;
                }
                let field = line.split(':').next()?.trim();
                if field.is_empty() {
                    return None;
                }
                Some(field.to_string())
            } else {
                let field = line.split([':', '?']).next()?.trim();
                if field.is_empty() || field.starts_with('}') {
                    return None;
                }
                Some(field.to_string())
            }
        })
        .collect()
}

/// Schema property names. The Python SDK keeps the JSON spelling, including
/// reserved words, because the functional `TypedDict(...)` form accepts any key.
fn schema_fields(schema: &serde_json::Value, def_name: &str, _py: bool) -> BTreeSet<String> {
    let props = schema["$defs"][def_name]["properties"]
        .as_object()
        .unwrap_or_else(|| panic!("schema.json has no $defs/{def_name}/properties"));
    props.keys().cloned().collect()
}

const LAYER_DEFS: &[&str] = &[
    "ContainerLayer",
    "RectLayer",
    "CircleLayer",
    "TextLayer",
    "SvgLayer",
    "ImageLayer",
    "VideoLayer",
    "WaveformLayer",
    "LottieLayer",
    "ParticlesLayer",
    "Mesh3dLayer",
];

const VALUE_DEFS: &[&str] = &[
    "Animation",
    "LinearGradient",
    "Layout",
    "Shadow",
    "TextSpan",
    "SpringConfig",
    "Echo",
    "IncludeLayer",
];

fn assert_fields_cover(schema: &serde_json::Value, base: &str, name: &str, body: &str, py: bool) {
    let expected = schema_fields(schema, name, py);
    let mut found = field_names(body, py);
    // Layer interfaces inherit `BaseLayer`; value defs do not.
    if LAYER_DEFS.contains(&name) {
        found.extend(field_names(base, py));
    }
    let missing: Vec<_> = expected.difference(&found).cloned().collect();
    let extra: Vec<_> = found.difference(&expected).cloned().collect();
    assert!(
        missing.is_empty() && extra.is_empty(),
        "{} {name} drifted from schema: missing {missing:?}, extra {extra:?}; \
         run `python3 scripts/gen_sdk.py`",
        if py { "rustren_types.py" } else { "rustren.d.ts" }
    );
}

#[test]
fn typescript_sdk_covers_schema_fields() {
    let schema = schema();
    let text = read("sdk/typescript/rustren.d.ts");
    let base = ts_interface(&text, "BaseLayer");

    for name in LAYER_DEFS.iter().chain(VALUE_DEFS.iter()) {
        let body = ts_interface(&text, name);
        assert_fields_cover(&schema, &base, name, &body, false);
    }
    for name in ["Canvas", "CompositionProfile", "AudioTrack", "Keyframe", "GradientStop"] {
        let body = ts_interface(&text, name);
        let fields = field_names(&body, false);
        assert!(
            !fields.is_empty(),
            "rustren.d.ts interface {name} has no fields"
        );
    }
}

#[test]
fn python_sdk_covers_schema_fields() {
    let schema = schema();
    let text = read("sdk/python/rustren_types.py");
    let base = py_class(&text, "BaseLayer");

    for name in LAYER_DEFS.iter().chain(VALUE_DEFS.iter()) {
        let body = py_class(&text, name);
        assert_fields_cover(&schema, &base, name, &body, true);
    }
    for name in ["Canvas", "CompositionProfile", "AudioTrack", "Keyframe", "GradientStop"] {
        assert!(
            !field_names(&py_class(&text, name), true).is_empty(),
            "rustren_types.py class {name} has no fields"
        );
    }
}

/// The small helper structs are inline in the schema, not `$defs`, so they are
/// checked against their parent property instead.
#[test]
fn inline_helper_types_match_schema() {
    let schema = schema();
    let defs = &schema["$defs"];
    let text = read("sdk/typescript/rustren.d.ts");

    let check = |generated: &str, expected: BTreeSet<String>| {
        let found = field_names(&ts_interface(&text, generated), false);
        let missing: Vec<_> = expected.difference(&found).cloned().collect();
        let extra: Vec<_> = found.difference(&expected).cloned().collect();
        assert!(
            missing.is_empty() && extra.is_empty(),
            "rustren.d.ts {generated}: missing {missing:?}, extra {extra:?}"
        );
    };

    let props_of = |value: &serde_json::Value| -> BTreeSet<String> {
        value["properties"]
            .as_object()
            .expect("properties")
            .keys()
            .cloned()
            .collect()
    };

    check(
        "GradientStop",
        props_of(&defs["LinearGradient"]["properties"]["stops"]["items"]),
    );
    check(
        "Keyframe",
        props_of(&defs["Animation"]["properties"]["keyframes"]["items"]),
    );

    // Keyframes are user-authored, so their generated TS type must reject a
    // misspelled field rather than silently accept it.
    let keyframe = ts_interface(&text, "Keyframe");
    assert!(
        keyframe.contains("time: number") || keyframe.contains("time:number"),
        "Keyframe.time must be required: {keyframe}"
    );
}

/// The Python SDK must spell fields exactly as JSON does so a copy-pasted
/// scene dict type-checks. Reserved words are handled by the functional
/// `TypedDict(...)` form instead of a `from_` alias.
#[test]
fn python_sdk_keeps_json_field_spelling() {
    let text = read("sdk/python/rustren_types.py");
    assert!(
        text.contains("\"from\": "),
        "rustren_types.py must declare the literal `from` key"
    );
    assert!(
        !text.contains("from_: "),
        "rustren_types.py must not alias `from` to `from_`"
    );
    // Compiled by the generator check; decoding here catches a broken module early.
    let output = match Command::new("python3")
        .args(["-c", "import sys; sys.path.insert(0, 'sdk/python'); import rustren_types as t; print(len(t.Layer.__args__))"])
        .current_dir(root())
        .output()
    {
        Ok(out) => out,
        Err(_) => {
            eprintln!("skipping: python3 not available");
            return;
        }
    };
    assert!(
        output.status.success(),
        "rustren_types.py failed to import:\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "12");
}

/// `required` in the schema must map to non-optional TS fields (and the reverse).
#[test]
fn typescript_required_fields_match_schema() {
    let schema = schema();
    let text = read("sdk/typescript/rustren.d.ts");

    let required = |body: &str| -> BTreeSet<String> {
        body.lines()
            .filter_map(|line| {
                let line = line.trim();
                if line.is_empty() || line.starts_with("/*") || line.starts_with("//") {
                    return None;
                }
                let (field, rest) = line.split_once(':')?;
                let field = field.trim();
                if rest.is_empty() || field.contains([' ', '\t']) {
                    return None;
                }
                if field.ends_with('?') {
                    return None;
                }
                Some(field.to_string())
            })
            .collect()
    };

    for name in LAYER_DEFS.iter().copied().chain(["IncludeLayer", "Animation", "TextSpan"]) {
        let expected: BTreeSet<String> = schema["$defs"][name]["required"]
            .as_array()
            .map(|a| a.iter().map(|v| v.as_str().unwrap().to_string()).collect())
            .unwrap_or_default();
        let body = ts_interface(&text, name);
        let found = required(&body);
        assert_eq!(
            found, expected,
            "rustren.d.ts {name} required/optional markers drifted from schema.json"
        );
    }
}

/// Generated enum literals must exist in `schema.json`, per-def where possible.
#[test]
fn sdk_enum_literals_come_from_schema() {
    let schema = schema();
    let defs = &schema["$defs"];

    let inline = |owner: &str, key: &str| -> BTreeSet<String> {
        defs[owner]["properties"][key]["enum"]
            .as_array()
            .unwrap_or_else(|| panic!("schema.json {owner}.{key}/enum must exist"))
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect()
    };

    // (generated type name, schema location) - some enums live in `$defs`,
    // others only exist inline on a layer or animation property.
    let sources: &[(&str, &str, &str)] = &[
        ("BlendMode", "$defs", "BlendMode"),
        ("AnimProperty", "Animation", "property"),
        ("Easing", "$defs", "Easing"),
        ("FitMode", "ImageLayer", "fit"),
    ];

    let text = read("sdk/typescript/rustren.d.ts");
    for &(name, owner, key) in sources {
        let marker = format!("export type {name} =");
        let start = text
            .lines()
            .position(|l| l.starts_with(&marker))
            .unwrap_or_else(|| panic!("rustren.d.ts has no type {name}"));
        // Single-line unions end on the first line; multi-line ones end with `;`.
        let mut lines = Vec::new();
        for line in text.lines().skip(start) {
            let done = line.ends_with(';');
            lines.push(line);
            if done {
                break;
            }
        }
        let body = lines.join("\n");
        let literals: BTreeSet<String> = body
            .split('"')
            .skip(1)
            .step_by(2)
            .map(str::to_string)
            .collect();
        let expected = if owner == "$defs" {
            defs[key]["enum"]
                .as_array()
                .unwrap_or_else(|| panic!("schema.json $defs/{key}/enum must exist"))
                .iter()
                .map(|v| v.as_str().unwrap().to_string())
                .collect()
        } else {
            inline(owner, key)
        };
        assert_eq!(
            literals, expected,
            "rustren.d.ts {name} literals drifted from schema.json"
        );
    }

    // Enums that only exist inline on a layer property.
    for (ts_name, owner, key) in [
        ("Anchor", "RectLayer", "anchor"),
        ("TrackMatte", "RectLayer", "track_matte"),
        ("TextAlign", "TextLayer", "text_align"),
        ("TextDirection", "TextLayer", "direction"),
    ] {
        let expect = inline(owner, key);
        let py = read("sdk/python/rustren_types.py");
        let line = py
            .lines()
            .find(|l| l.starts_with(&format!("{ts_name} = Literal[")))
            .unwrap_or_else(|| panic!("rustren_types.py has no {ts_name}"));
        let literals: BTreeSet<String> = line
            .split('"')
            .skip(1)
            .step_by(2)
            .map(str::to_string)
            .collect();
        assert_eq!(literals, expect, "rustren_types.py {ts_name} drifted");
    }
}

/// When Python is available, the generator's own check must agree byte-for-byte.
#[test]
fn sdk_generator_check_passes() {
    let script = root().join("scripts/gen_sdk.py");
    assert!(script.exists(), "scripts/gen_sdk.py is missing");

    let output = match Command::new("python3").arg(&script).arg("--check").output() {
        Ok(out) => out,
        Err(_) => {
            eprintln!("skipping: python3 not available");
            return;
        }
    };
    assert!(
        output.status.success(),
        "gen_sdk.py --check failed:\n{}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );

    // Byte parity with the generator does not prove the Python output parses
    // (e.g. a reserved-word field name would be emitted happily).
    let compiled = Command::new("python3")
        .args(["-m", "py_compile", "sdk/python/rustren_types.py"])
        .current_dir(root())
        .output()
        .expect("run python3 -m py_compile");
    assert!(
        compiled.status.success(),
        "rustren_types.py does not compile:\n{}",
        String::from_utf8_lossy(&compiled.stderr)
    );
}

/// `--check` must be wired into the script, so a stale SDK is never silent.
#[test]
fn generator_is_committed_with_its_outputs() {
    for path in [
        "scripts/gen_sdk.py",
        "sdk/typescript/rustren.d.ts",
        "sdk/python/rustren_types.py",
    ] {
        assert!(Path::new(&root()).join(path).exists(), "{path} is missing");
    }
    let script = read("scripts/gen_sdk.py");
    assert!(
        script.contains("\"Generated by scripts/gen_sdk.py\"")
            || script.contains("Generated by scripts/gen_sdk.py"),
        "the SDK header must name the generator"
    );
    for path in ["sdk/typescript/rustren.d.ts", "sdk/python/rustren_types.py"] {
        let text = read(path);
        assert!(
            text.contains("Generated by scripts/gen_sdk.py"),
            "{path} must carry the generated-file header"
        );
    }
}
